/**
 * Test Prisma Client to verify it works
 */
import { PrismaClient } from '@prisma/client';

const prisma = new PrismaClient({
  log: ['query', 'error', 'warn'],
});

async function testPrismaClient() {
  try {
    console.log('Testing Prisma Client connection...');
    
    // Test 1: Raw query
    console.log('\n1. Testing $queryRaw...');
    const rawResult = await prisma.$queryRaw`SELECT 1 as test`;
    console.log('✅ $queryRaw works:', rawResult);

    // Test 2: Count query
    console.log('\n2. Testing user.count()...');
    const userCount = await prisma.user.count();
    console.log('✅ user.count() works:', userCount);

    // Test 3: Find unique
    console.log('\n3. Testing user.findUnique()...');
    const user = await prisma.user.findUnique({
      where: { email: 'admin@example.com' },
      include: { credentials: true },
    });
    console.log('✅ user.findUnique() works:', user ? `Found user: ${user.email}` : 'User not found');

    await prisma.$disconnect();
    console.log('\n✅ All Prisma Client tests passed!');
    process.exit(0);
  } catch (error: any) {
    console.error('\n❌ Prisma Client test failed:');
    console.error('Error:', error.message);
    console.error('Code:', error.code);
    console.error('Meta:', error.meta);
    await prisma.$disconnect();
    process.exit(1);
  }
}

testPrismaClient();
